import {censusReport} from './demographics.js?v=economic-cap-1';
import {annualPower} from './power-accounting.js?v=economic-cap-1';
import {workforceOutlook,workforceAgeTable} from './workforce.js?v=economic-cap-1';
import {wasteBreakdown} from './waste-accounting.js?v=economic-cap-1';
import {POWER_PLANTS,plantCapacity} from './power.js?v=economic-cap-1';
import {wastePower} from './utilities.js?v=economic-cap-1';
export function populationBreakdown(c){const s=c.stats,total=s.population,workers=s.commuters,employed=workers-s.unemployed;return{total,workers,share:total?workers/total*100:0,rows:[{name:'Workers with reachable jobs',people:employed},{name:'Workers without reachable jobs',people:s.unemployed},{name:'Other residents',people:Math.max(0,total-workers)}].map(r=>({...r,percent:total?r.people/total*100:0}))};}
export function powerBreakdown(c){const n=Math.sqrt(c.tiles.length),rows=Object.entries(POWER_PLANTS).map(([kind,d])=>{const roots=c.tiles.filter(t=>t.type===kind&&t.root===t.y*n+t.x);return{kind,name:d.name,plants:roots.length,capacity:roots.reduce((sum,t)=>sum+plantCapacity(t),0)};});const burners=c.tiles.filter(t=>t.type==='wasteEnergy');if(burners.length)rows.push({kind:'wasteEnergy',name:'Waste-to-energy',plants:burners.length,capacity:burners.reduce((sum,t)=>sum+wastePower(t),0)});const total=rows.reduce((sum,r)=>sum+r.capacity,0);return{total,rows:rows.filter(r=>r.plants).map(r=>({...r,percent:total?r.capacity/total*100:0}))};}
export function breakdownCharts(c){const annual=annualPower(c),workforce=workforceOutlook(c),waste=wasteBreakdown(c),pop=populationBreakdown(c),power=powerBreakdown(c),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:1}),colors=['#c4ed89','#ffc483','#8ddce8','#a9a2ec','#d8bd92','#79cbb3','#f1a9b0','#d4e2af','#b0c9ce'];
 const bar=(rows,value)=>`<div style="display:flex;height:20px;border-radius:4px;overflow:hidden;background:#304b50" aria-hidden="true">${rows.map((r,i)=>`<span style="width:${r[value]}%;background:${colors[i%colors.length]}"></span>`).join('')}</div>`;
 return `${censusReport(c)}<details><summary>Garbage · disposal methods and yearly generation</summary>${waste?`<p>Latest recorded: city month ${waste.month}. Generated locally: ${fmt(waste.generated)} units; imported: ${fmt(waste.imported)}; still uncollected: ${fmt(waste.waiting)}.</p>${bar(waste.methods,'percent')}<div class="table-scroll"><table><thead><tr><th>Method</th><th>Units handled</th><th>Share handled</th></tr></thead><tbody>${waste.methods.map((r,i)=>`<tr><td><span style="color:${colors[i]}">■</span> ${r.name}</td><td>${fmt(r.amount)}</td><td>${fmt(r.percent)}%</td></tr>`).join('')}</tbody></table></div><p>Local garbage generated in the last 12 months: ${fmt(waste.yearGenerated)} units (${waste.recordedMonths}/12 months recorded${waste.recordedMonths<12?'; partial total':''}).</p><p>Disposal shares include imported waste and older backlogs. Landfill decomposition frees space but is not counted as new disposal.</p>`:'<p>No disposal records yet. Run one month to start recording. Older saves do not contain this breakdown.</p>'}</details><details><summary>Population · workforce and employment</summary><p>${fmt(pop.total)} residents · ${fmt(pop.workers)} workers (${fmt(pop.share)}% of residents).</p>${bar(pop.rows,'percent')}<div class="table-scroll"><table><thead><tr><th>Population group</th><th>People</th><th>Share of residents</th></tr></thead><tbody>${pop.rows.map((r,i)=>`<tr><td><span style="color:${colors[i]}">■</span> ${r.name}</td><td>${fmt(r.people)}</td><td>${fmt(r.percent)}%</td></tr>`).join('')}</tbody></table></div><p>At ${fmt(workforce.lifeExpectancy)} years of life expectancy, ${fmt(workforce.share*100)}% of residents participate in the workforce. That is ${fmt(Math.abs(workforce.healthDifference))} ${workforce.healthDifference>=0?'more':'fewer'} workers than the 59-year health baseline for this population and age mix. Longer lives expand the workforce; those residents still need reachable jobs. Reachable jobs reflect current road and transit routes. Other residents are outside the modeled workforce.</p>${workforceAgeTable(c)}</details><details><summary>Electricity · domestic supply by plant type</summary><p>${fmt(power.total)} units of current domestic capacity.</p>${bar(power.rows,'percent')}<div class="table-scroll"><table><thead><tr><th>Source</th><th>Plants</th><th>Capacity</th><th>Share</th></tr></thead><tbody>${power.rows.map((r,i)=>`<tr><td><span style="color:${colors[i%colors.length]}">■</span> ${r.name}</td><td>${r.plants}</td><td>${fmt(r.capacity)}</td><td>${fmt(r.percent)}%</td></tr>`).join('')||'<tr><td colspan="4">No domestic power plants.</td></tr>'}</tbody></table></div><p>Capacity includes aging, elevation effects on wind, and waste-to-energy fuel actually burned last month. Neighbor imports are separate. A city-wide total does not guarantee supply to disconnected grids. Capacity is available supply, not output delivered.</p><h3>Electricity supplied over the last 12 months</h3>${annual?`<p>${fmt(annual.total)} energy units generated domestically · ${annual.months}/12 months recorded${annual.months<12?' (partial total)':''}.</p>${bar(annual.sources,'percent')}<div class="table-scroll"><table><thead><tr><th>Source</th><th>Energy supplied</th><th>Share</th></tr></thead><tbody>${annual.sources.map(r=>`<tr><td>${r.name}</td><td>${fmt(r.amount)}</td><td>${fmt(r.percent)}%</td></tr>`).join('')||'<tr><td colspan="3">No domestic output recorded.</td></tr>'}</tbody></table></div><p>Imported: ${fmt(annual.imported)} · Exported: ${fmt(annual.exported)} · Delivered to local demand: ${fmt(annual.served)} energy units.</p>`:'<p>Run one month to start recording supply. Older saves have no production records.</p>'}<p>Output counts electricity delivered to demand and exports, apportioned among plants by their capacity within each connected grid. Unused capacity is excluded. One month of supply contributes one month of energy units; these are game units, not kilowatt-hours.</p></details>`;
}
